// Kaydırmayla ilerleyen anlatının saf mantığı: kaydırma konumundan adım konumu, sekme dolgusu ve yazımlar. Sayılar ABACUS'tandır.
import { countText } from "../lib/shop-format";

/** Görüş alanında "okuma çizgisi": adım geçişi görüş alanının bu oranında olur (üstten). */
export const READ_LINE = .4;

const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value));

/**
 * Adım konumu (ondalık): 0 ilk adımın başı, 1 ikinci adımın başı... `tops` adım metinlerinin kaydırma alanındaki üst kenarlarıdır.
 * Okuma çizgisi iki adımın arasındaysa aradaki oranı verir; son adımdan sonrası son adımda kalır.
 */
export function stepPosition(tops: number[], scrollTop: number, viewport: number): number {
  if (!tops.length) return 0;
  const line = scrollTop + viewport * READ_LINE;
  if (line <= tops[0]!) return 0;
  for (let at = 0; at < tops.length - 1; at++) {
    if (line < tops[at + 1]!) return at + (line - tops[at]!) / (tops[at + 1]! - tops[at]! || 1);
  }
  return tops.length - 1;
}

/** Etkin adım: konuma en yakın tam adım. */
export const activeStep = (position: number, count: number): number => clamp(Math.round(position), 0, Math.max(0, count - 1));

/** Sekme dolgusu (0–1): sekme, konum bir önceki adımdan bu adıma ilerledikçe dolar. İlk sekme başlangıçta doludur. */
export const tabFill = (position: number, index: number): number => clamp(position - index + 1, 0, 1);

/** Bir adımın başına kaydırma hedefi: adım metni okuma çizgisinin biraz üstüne gelir. */
export const scrollTargetFor = (tops: number[], index: number): number => Math.max(0, (tops[index] ?? 0));

export const stepLabel = (index: number, total: number): string => `Adım ${countText(index + 1)}/${countText(total)}`;
export const COPIED_TEXT = "Bağlantı kopyalandı";
export const SENT_TEXT = "Gönderildi";
export const FAILED_TEXT = (what: string): string => `${what} yapılamadı`;

.root { --story-h: clamp(22rem, 55svh, 37.5rem); container-type: inline-size; display: grid; gap: var(--space-3); min-width: 0; color: var(--foreground); }
.tabs { display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: var(--space-2); }
.tab { display: grid; gap: var(--space-2); padding: var(--space-1) 0 0; transition: color var(--duration-fast) var(--ease-standard); border: 0; background: none; color: var(--text-secondary); font: inherit; font-size: var(--text-xs); text-align: left; cursor: pointer; }
.tab[aria-selected="true"] { color: var(--foreground); }
.tab:hover { color: var(--foreground); }
.tab:active .tabBar { transform: scaleY(1.6); }
.tab:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 3px; border-radius: 2px; }
.tabBar { display: block; height: 4px; border-radius: var(--radius-pill); background: var(--neutral-3); overflow: hidden; transition: transform var(--duration-fast) var(--ease-standard); }
.tabBar i { display: block; height: 100%; border-radius: var(--radius-pill); background: var(--foreground); transform-origin: left; }
.tabLabel { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.area { position: relative; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: var(--space-8); height: var(--story-h); overflow-y: auto; overscroll-behavior: contain; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); }
.area:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.stageWrap { grid-column: 2; grid-row: 1; position: sticky; top: 0; align-self: start; height: var(--story-h); display: grid; place-items: center; padding: var(--space-5); }
.stage { position: relative; width: 100%; height: 100%; max-height: 24rem; overflow: hidden; border: 1px solid var(--border-subtle); border-radius: var(--radius-panel); background: var(--surface-muted); box-shadow: var(--shadow-raised); }
.steps { grid-column: 1; grid-row: 1; margin: 0; padding: 0 0 0 var(--space-8); list-style: none; }
.step { display: grid; align-content: center; gap: var(--space-2); min-height: var(--story-h); padding-right: var(--space-2); opacity: .4; transform: translateY(6px); transition: opacity var(--duration-standard) var(--ease-standard), transform var(--duration-considered) var(--ease-standard); }
.step[data-active] { opacity: 1; transform: none; }
.kicker { margin: 0; color: var(--accent-strong); font-size: var(--text-xs); font-weight: 500; letter-spacing: .04em; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.text { margin: 0; max-width: 28rem; color: var(--text-secondary); font-size: var(--text-lg); line-height: var(--leading-body); }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-2); }
.root[data-reduced] .step, .root[data-reduced] .tab, .root[data-reduced] .tabBar { transition: none; transform: none; }
@media (prefers-reduced-motion: reduce) { .step, .tab, .tabBar { transition: none; transform: none; } }
@container (max-width: 700px) {
  .area { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .stageWrap { grid-column: 1; grid-row: 1; z-index: 1; height: calc(var(--story-h) * .6); padding: var(--space-3); background: var(--surface); border-bottom: 1px solid var(--border-subtle); }
  .steps { grid-column: 1; grid-row: 2; padding: 0 var(--space-4); }
  .step { min-height: calc(var(--story-h) * .7); }
  .title { font-size: var(--text-2xl); }
  .text { font-size: var(--text-base); }
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { motion, useMotionValue, useSpring, useTransform, type MotionValue } from "motion/react";
import { Button } from "../button/button";
import { useAnnouncer } from "../lib/shop-parts";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { COPIED_TEXT, FAILED_TEXT, SENT_TEXT, activeStep, scrollTargetFor, stepLabel, stepPosition, tabFill } from "./scroll-story-format";
import styles from "./scroll-story.module.css";

export interface StoryStep {
  id: string;
  title: string;
  text: string;
  /** Adım etkinleşince kibar canlı bölgede duyurulan sahne durumu ("Gelen kutusunda yeni mesaj var"). */
  status?: string;
}

/** `renderStage`e verilen bağlam: `position` adım konumudur (0 ilk adım, 1 ikinci adım...; yayla yumuşar), `active` en yakın tam adımdır. */
export interface StageContext { position: MotionValue<number>; active: number; reduced: boolean }

/** Bir ürünü dört adım gibi kısa bir akışta anlatan tanıtım bölümü için kullanın: kendi içinde kayan metin alanı, ilerledikçe dolan adım sekmeleri ve metne göre değişen sabit sahne. Tek paragraflık kaydırma vurgusu ya da tek önce/sonra anahtarı için değil. Sahneyi `renderStage` ile siz çizersiniz; gerçek paylaşım ve kopyalamayı `actions` ile bağlarsınız. */
export interface ScrollStoryProps {
  label: string;
  steps: StoryStep[];
  renderStage: (context: StageContext) => ReactNode;
  /** Son adımın altında "Bağlantıyı kopyala" ve "Kanala gönder" düğmeleri çıkar; sonuç duyurulur. */
  actions?: { onCopyLink?: () => Promise<void>; onSend?: () => Promise<void> };
}

function Tab({ index, step, total, position, active, onSelect, onKeyDown, tabRef, controls }: { index: number; step: StoryStep; total: number; position: MotionValue<number>; active: boolean; onSelect: () => void; onKeyDown: (event: KeyboardEvent) => void; tabRef: (node: HTMLButtonElement | null) => void; controls: string }) {
  const scale = useTransform(position, value => tabFill(value, index));
  return <button ref={tabRef} type="button" role="tab" id={`${controls}-tab-${index}`} aria-selected={active} aria-controls={`${controls}-step-${index}`} tabIndex={active ? 0 : -1} className={styles.tab} onClick={onSelect} onKeyDown={onKeyDown}>
    <span className={styles.tabBar} aria-hidden="true"><motion.i style={{ scaleX: scale }} /></span>
    <span className={styles.tabLabel}>{stepLabel(index, total)} · {step.title}</span>
  </button>;
}

export function ScrollStory({ label, steps, renderStage, actions }: ScrollStoryProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const area = useRef<HTMLDivElement>(null);
  const sections = useRef<(HTMLElement | null)[]>([]);
  const tabs = useRef<(HTMLButtonElement | null)[]>([]);
  const raw = useMotionValue(0);
  const spring = useSpring(raw, { stiffness: 170, damping: 26, mass: .6 });
  const position = reduced ? raw : spring;
  const [active, setActive] = useState(0);
  const [live, announce] = useAnnouncer();
  const frame = useRef(0);
  const lastStatus = useRef(-1);

  const tops = useCallback(() => sections.current.map(node => node?.offsetTop ?? 0), []);
  const read = useCallback(() => {
    const node = area.current;
    if (!node) return;
    const offsets = tops();
    // Okuma çizgisi yüzünden en üstte konum 0'dan büyük çıkar; sahne ilk adımda tam başlangıç hâlinde dursun diye baştan sona yeniden ölçeklenir.
    const base = stepPosition(offsets, 0, node.clientHeight), end = steps.length - 1;
    const next = end > base ? Math.max(0, Math.min(end, (stepPosition(offsets, node.scrollTop, node.clientHeight) - base) / (end - base) * end)) : 0;
    raw.set(next);
    setActive(activeStep(next, steps.length));
  }, [raw, steps.length, tops]);

  useEffect(() => {
    const node = area.current;
    if (!node) return;
    const onScroll = () => { if (frame.current) return; frame.current = requestAnimationFrame(() => { frame.current = 0; read(); }); };
    node.addEventListener("scroll", onScroll, { passive: true });
    const observer = typeof ResizeObserver !== "undefined" ? new ResizeObserver(read) : null;
    observer?.observe(node);
    read();
    return () => { node.removeEventListener("scroll", onScroll); observer?.disconnect(); cancelAnimationFrame(frame.current); frame.current = 0; };
  }, [read]);
  useEffect(() => {
    if (lastStatus.current === active) return;
    lastStatus.current = active;
    if (active > 0 || steps[0]?.status) { const status = steps[active]?.status; if (status) announce(status); }
  }, [active, steps, announce]);

  const go = (index: number) => {
    const node = area.current;
    if (!node) return;
    node.scrollTo({ top: scrollTargetFor(tops(), index) - node.clientHeight * .05, behavior: reduced ? "auto" : "smooth" });
  };
  const tabKey = (event: KeyboardEvent, index: number) => {
    const next = event.key === "ArrowRight" ? Math.min(steps.length - 1, index + 1) : event.key === "ArrowLeft" ? Math.max(0, index - 1) : event.key === "Home" ? 0 : event.key === "End" ? steps.length - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    tabs.current[next]?.focus();
    go(next);
  };
  const run = async (task: (() => Promise<void>) | undefined, done: string, what: string) => {
    if (!task) return;
    try { await task(); announce(done); } catch { announce(FAILED_TEXT(what)); }
  };

  const last = steps.length - 1;
  return <section className={styles.root} aria-label={label} data-reduced={reduced || undefined}>
    <div className={styles.tabs} role="tablist" aria-label={`${label}: adımlar`}>
      {steps.map((step, at) => <Tab key={step.id} index={at} step={step} total={steps.length} position={position} active={active === at} controls={uid} onSelect={() => go(at)} onKeyDown={event => tabKey(event, at)} tabRef={node => { tabs.current[at] = node; }} />)}
    </div>
    <div ref={area} className={styles.area} tabIndex={0} role="region" aria-label={`${label}: kaydırarak ilerleyin`}>
      <div className={styles.stageWrap}><div className={styles.stage} aria-hidden="true">{renderStage({ position, active, reduced })}</div></div>
      <ol className={styles.steps}>
        {steps.map((step, at) => <li key={step.id} id={`${uid}-step-${at}`} ref={node => { sections.current[at] = node; }} className={styles.step} role="tabpanel" aria-labelledby={`${uid}-tab-${at}`} data-active={active === at || undefined} aria-current={active === at ? "step" : undefined}>
          <p className={styles.kicker}>{stepLabel(at, steps.length)}</p>
          <h3 className={styles.title}>{step.title}</h3>
          <p className={styles.text}>{step.text}</p>
          {at === last && actions && <div className={styles.actions}>
            {actions.onCopyLink && <Button variant="secondary" size="sm" onClick={() => run(actions.onCopyLink, COPIED_TEXT, "Kopyalama")}>Bağlantıyı kopyala</Button>}
            {actions.onSend && <Button variant="secondary" size="sm" onClick={() => run(actions.onSend, SENT_TEXT, "Gönderme")}>Kanala gönder</Button>}
          </div>}
        </li>)}
      </ol>
    </div>
    {live}
  </section>;
}

export default ScrollStory;
